using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;

[McpServerToolType]
public static class WeatherTools
{
    [McpServerTool, Description("Gets the current weather for a given city.")]
    public static async Task<string> GetCurrentWeather(
        IHttpClientFactory httpClientFactory,
        [Description("City name, e.g. 'London' or 'New York'")] string city,
        CancellationToken cancellationToken = default)
    {
        var client = httpClientFactory.CreateClient("WeatherApi");
        var response = await client.GetAsync($"current.json?q={Uri.EscapeDataString(city)}", cancellationToken);

        if (!response.IsSuccessStatusCode)
        {
            return $"Error: received {response.StatusCode} from weather API.";
        }

        var json = await response.Content.ReadFromJsonAsync<JsonElement>(cancellationToken);
        var current = json.GetProperty("current");

        return $"""
            Weather for {city}:
              Temperature: {current.GetProperty("temp_c")}°C / {current.GetProperty("temp_f")}°F
              Condition:   {current.GetProperty("condition").GetProperty("text")}
              Humidity:    {current.GetProperty("humidity")}%
              Wind:        {current.GetProperty("wind_kph")} kph
            """;
    }

    [McpServerTool, Description("Searches for cities matching a query and returns matching location names.")]
    public static async Task<string> SearchCities(
        IHttpClientFactory httpClientFactory,
        [Description("Partial city name to search for")] string query,
        CancellationToken cancellationToken = default)
    {
        var client = httpClientFactory.CreateClient("WeatherApi");
        var results = await client.GetFromJsonAsync<JsonElement[]>(
            $"search.json?q={Uri.EscapeDataString(query)}", cancellationToken);

        if (results is null || results.Length == 0)
            return "No cities found.";

        return string.Join("\n", results.Select(r =>
            $"{r.GetProperty("name")} — {r.GetProperty("region")}, {r.GetProperty("country")}"));
    }
}

